            askFree: 'Write your template linker that opens the limiting sentence in Body B.',
            ok: 'Nevertheless',
            wrong: [
              ['Furthermore', 'This adds a supporting point; the next sentence limits the view.'],
              ['Therefore', 'This signals a consequence; the next sentence runs against the view.'],
              ['For instance', 'The case has been given; the next sentence is a limit.']
            ],
            shape: 'one linker of contrast', expect: 'Nevertheless (also accepted: nonetheless, however, even so)',
