            accept: [['global|world|broad|sweeping|survey'], ['superficial|shallow|fragment|scattered|thin|no grounding|no anchor']],
            reject: [{ re: 'no pupil|ever retain', hint: 'Overstated: hedge the claim.' },
              { re: 'examine fairly|settled canon', hint: 'That is about examinations.' },
              { re: 'purely national|celebration', hint: 'That is the limit of the first view.' }],
